package com.bank.rotatedsearch;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds a rate's index in a rotated checkpoint list for National Bank of India.
public class RotatedSearch {
    private static final Logger log = Logger.getLogger(RotatedSearch.class.getName());

    // Index of target in a rotated sorted array (distinct). O(log n), O(1).
    public int indexOfRate(BigDecimal[] rates, BigDecimal target) {
        if (rates == null || rates.length == 0) {
            return -1;
        }
        int lo = 0;
        int hi = rates.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            int cmpMid = rates[mid].compareTo(target);
            if (cmpMid == 0) {
                final int found = mid;
                log.info(() -> "Found rate at index " + found);
                return mid;                              // exact match
            }
            if (rates[lo].compareTo(rates[mid]) <= 0) {
                // Left half [lo..mid] is sorted.
                if (target.compareTo(rates[lo]) >= 0 && target.compareTo(rates[mid]) < 0) {
                    hi = mid - 1;                        // target in left half
                } else {
                    lo = mid + 1;                        // search right half
                }
            } else {
                // Right half [mid..hi] is sorted.
                if (target.compareTo(rates[mid]) > 0 && target.compareTo(rates[hi]) <= 0) {
                    lo = mid + 1;                        // target in right half
                } else {
                    hi = mid - 1;                        // search left half
                }
            }
        }
        log.warning(() -> "Rate " + target + " not found");
        return -1;                                       // absent
    }
}
