package com.bank.rotatedsearch;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: search a rotated checkpoint list.
public class RotatedSearchDemo {
    private static final Logger log = Logger.getLogger(RotatedSearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        RotatedSearch search = new RotatedSearch();

        // Rotated ascending interest-rate checkpoints (%).
        BigDecimal[] rotated = { bd("4"), bd("5"), bd("6"), bd("7"), bd("0"), bd("1"), bd("2") };
        int idx = search.indexOfRate(rotated, bd("0"));
        log.info(() -> "Index of rate 0 = " + idx);

        int missing = search.indexOfRate(rotated, bd("3"));
        log.info(() -> "Index of rate 3 = " + missing);
    }
}
